(ns armate.archimate.core (:require [clojure.string :as s] [armate.archimate.collector :as acl] [armate.archimate.metamodel.derivation.core :as dcr] [armate.archimate.metamodel.meta :as mt] [armate.archimate.viz.saver :as svr] [armate.archimate.multi-graph :as mg] [armate.archimate.archi.parser :as arr] [armate.archimate.plantuml.parser :as prr] [armate.archimate.viz.align.neighbours :as alg] [armate.archimate.viz.combiner :as viz]))
(defn get-stats [context] (let [relations (mg/get-relationships (:relations context)) groups (group-by (comp :derivate last) relations)] {:types (count (:types context)), :elements (count (:elements context)), :relations {:original (count (groups nil [])), :nesting (count (groups :nesting [])), :certain (count (groups :certain [])), :potential (count (groups :potential []))}, :lints (count (:lints context))}))
(defn analyze-file [file-path] (let [content (slurp file-path)] (if (empty? content) (throw (ex-info "File is empty" {:file-path file-path})) (prr/analyze-content content))))
(defn stat-file [file-path] (try (-> file-path analyze-file dcr/derivate-relations get-stats) (catch clojure.lang.ExceptionInfo e {:exception {:message (ex-message e), :data (ex-data e)}})))
(defn filter-relationships [context key predicate] (update context key (partial mg/filter-relationships predicate)))
(defn generate-derivate-file [predicate file-path name-suffix] (try (-> (analyze-file file-path) (acl/ungroup) (dcr/derivate-relations) (filter-relationships :relations predicate) (acl/erase-unbinded-elements) (dissoc :connectors) (svr/save-puml (svr/add-suffix file-path name-suffix))) (catch clojure.lang.ExceptionInfo e {:msg (ex-message e), :data (ex-data e)})))
(comment)
